CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE api_keys (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), token_hash BYTEA NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ);
CREATE TABLE projects (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, owner_id BIGINT NOT NULL REFERENCES users(id), private BOOLEAN NOT NULL DEFAULT true, UNIQUE(owner_id, name));
CREATE TABLE paths (id BIGSERIAL PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), rel_path TEXT NOT NULL, UNIQUE(project_id, rel_path));
CREATE TABLE heartbeats (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), project_id BIGINT REFERENCES projects(id), time DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), category TEXT, language TEXT, editor TEXT, is_write BOOLEAN, path_id BIGINT REFERENCES paths(id), line_additions INTEGER, line_deletions INTEGER, ai_model TEXT, ai_session TEXT, ai_prompt_length INTEGER, ai_line_changes INTEGER, human_line_changes INTEGER, source TEXT, source_type TEXT, machine_hash TEXT, operating_system TEXT, dedupe_key TEXT NOT NULL, UNIQUE(user_id, dedupe_key));
CREATE TABLE events (id TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), project_id BIGINT REFERENCES projects(id), occurred_at TIMESTAMPTZ NOT NULL, payload JSONB NOT NULL);
CREATE TABLE repositories (id BIGSERIAL PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id), remote_owner TEXT, remote_name TEXT, public BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE commits (sha TEXT PRIMARY KEY, repository_id BIGINT NOT NULL REFERENCES repositories(id), user_id BIGINT NOT NULL REFERENCES users(id), pushed_at TIMESTAMPTZ, tree_hash TEXT NOT NULL);
CREATE TABLE rollups (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), project_id BIGINT REFERENCES projects(id), day DATE NOT NULL, credited_seconds BIGINT NOT NULL, UNIQUE(user_id, project_id, day));
CREATE TABLE heartbeat_exclusions (id BIGSERIAL PRIMARY KEY, heartbeat_id BIGINT NOT NULL REFERENCES heartbeats(id), user_id BIGINT NOT NULL REFERENCES users(id), reason TEXT NOT NULL);
CREATE TABLE checkpoints (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), cursor TEXT NOT NULL);
CREATE TABLE submissions (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), project_id BIGINT NOT NULL REFERENCES projects(id), commit_sha TEXT NOT NULL REFERENCES commits(sha), tree_hash TEXT NOT NULL, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, project_id, commit_sha, tree_hash));
